"Prends un fichier <b>.gguf</b>. Sur la page du modèle (onglet « Files »), choisis celui qui finit par <b>Q4_K_M.gguf</b> : c'est le meilleur compromis. Ton PC a {} Go de mémoire : prends un fichier de <b>moins de {} Go</b>. Les noms avec « Instruct » ou « Chat » savent discuter ; « Translate » sont faits pour traduire.",
'Prends un fichier <b>.safetensors</b> de type « Checkpoint » (modèle complet). Sur Civitai, filtre sur « Checkpoint ». SD 1.5 marche partout ; SDXL et FLUX demandent une bonne carte graphique.',
'Prends un modèle <b>ACE-Step</b> en <b>.safetensors</b> (version « all in one » / « aio »).',
"Prends les <b>deux</b> fichiers d'une voix Piper : le <b>.onnx</b> et le <b>.onnx.json</b> (glisse le .onnx, garde le .json à côté), ou un .zip qui les contient.",
"⛔ Je refuse les fichiers <b>.ckpt</b>, <b>.pt</b> et <b>.bin</b> : ce vieux format peut cacher un programme. Il existe presque toujours une version .safetensors ou .gguf. Les filtres de Viki (pas d'images choquantes) restent actifs quel que soit le modèle.",
