'The fix if the natural voice lags: Pocket TTS by Kyutai (a French lab), a model 5 times smaller than Chatterbox, made for the processor. French voice “Estelle” included, and it also imitates your voice samples. About 1 GB to download, only once.',
'The natural voice imitates the chosen sample: 10 to 30 seconds, one person speaking calmly, no music or noise. Use your own voice, or that of someone who agrees.',
'The natural voice uses a lot of memory: I can pause it during the cut-out.',
'The “Estelle” voice works right away. For it to imitate YOUR sample, Kyutai asks you to accept its terms of use (free, only once):\n1. Create a Hugging Face account and accept the terms on the model page.\n2. Create a read-only token (“Read”) and paste it below.\nThe terms forbid imitating someone without their consent: use your own voice or that of someone who agrees.',
