'La lista de paquetes por actualizar y, en Arch, las últimas noticias de archlinux.org (a veces hay que actuar a mano antes de actualizar). La actualización se lanza en una terminal.',
'El tiempo real usa internet.',
'El reconocimiento de voz todavía no está instalado.',
'La solución si la voz natural va lenta: Pocket TTS de Kyutai (laboratorio francés), un modelo 5 veces más pequeño que Chatterbox, hecho para el procesador. Incluye la voz francesa «Estelle», y también imita tus muestras de voz. Unos 1 GB que descargar, una sola vez.',
'La voz natural imita la muestra elegida: de 10 a 30 segundos, una sola persona que hable con calma, sin música ni ruido. Usa tu voz, o la de alguien que esté de acuerdo.',
'La voz natural ocupa mucha memoria: puedo pausarla mientras dura el recorte.',
'La voz «Estelle» funciona enseguida. Para que imite TU muestra, Kyutai pide aceptar sus condiciones de uso (gratis, una sola vez):\n1. Crea una cuenta de Hugging Face y acepta las condiciones en la página del modelo.\n2. Crea un token de solo lectura («Read») y pégalo abajo.\nLas condiciones prohíben imitar a alguien sin su permiso: usa tu voz o la de una persona que esté de acuerdo.',
