'<b>🗣️ Para su voz</b>',
'Elige un archivo <b>.gguf</b>. En la página del modelo (pestaña « Files »), toma el que termina en <b>Q4_K_M.gguf</b>: el mejor equilibrio. Tu PC tiene {} GB de memoria: elige un archivo de <b>menos de {} GB</b>. Los nombres con « Instruct » o « Chat » saben charlar; los « Translate » están hechos para traducir.',
'Elige un archivo <b>.safetensors</b> de tipo « Checkpoint » (modelo completo). En Civitai, filtra por « Checkpoint ». SD 1.5 funciona en todas partes; SDXL y FLUX necesitan una buena tarjeta gráfica.',
'Elige un modelo <b>ACE-Step</b> en <b>.safetensors</b> (versión « all in one » / « aio »).',
'Toma los <b>dos</b> archivos de una voz Piper: el <b>.onnx</b> y el <b>.onnx.json</b> (arrastra el .onnx y deja el .json al lado), o un .zip que los contenga.',
'⛔ Rechazo los archivos <b>.ckpt</b>, <b>.pt</b> y <b>.bin</b>: ese formato antiguo puede esconder un programa. Casi siempre hay una versión .safetensors o .gguf. Los filtros de Viki (nada de imágenes chocantes) siguen activos sea cual sea el modelo.',
